function incoherence_index(n, F):
    if F is empty: return 0
    if 0 in F: return 1
    frontier <- { a mod n : a in F }
    visited  <- frontier
    length   <- 1
    while frontier nonempty and length <= n:
        next <- {}
        for s in frontier:
            for a in F:
                t <- (s + a) mod n
                if t == 0: return length + 1
                if t not in visited:
                    add t to visited and to next
        frontier <- next
        length   <- length + 1
    return 0

function is_maximal(n, F):
    reachable <- {0}
    repeat until no change:
        for r in reachable:
            for a in F:
                add (r + a) mod n to reachable
    return |reachable| == n

